(function() {
  'use strict';

  const EmojiSkyTheme = {
    container: null,
    resizeTimer: null,
    resizeHandler: null,
    emojiList: ['🌈', '✨', '💖', '🐱', '🌸', '🍓', '🧸', '☁️', '🍬', '🪄', '⭐️', '🐰'],

    init() {
      if (document.getElementById('emoji-sky-theme')) {
        this.container = document.getElementById('emoji-sky-theme');
        this.populateEmojis();
        return;
      }

      this.createContainer();
      this.populateEmojis();
      this.observeResize();

      document.body.classList.add('emoji-sky-theme-active');
      console.log('Emoji天空主题已启用');
    },

    createContainer() {
      const container = document.createElement('div');
      container.id = 'emoji-sky-theme';
      container.className = 'emoji-sky-layer';
      container.setAttribute('aria-hidden', 'true');
      document.body.insertAdjacentElement('afterbegin', container);
      this.container = container;
    },

    populateEmojis() {
      if (!this.container) return;

      const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
      const total = prefersReducedMotion.matches ? 20 : this.calculateDensity();
      const fragment = document.createDocumentFragment();

      for (let i = 0; i < total; i++) {
        const emoji = document.createElement('span');
        emoji.className = 'emoji-sky-item';
        emoji.textContent = this.emojiList[i % this.emojiList.length];
        emoji.style.setProperty('--emoji-left', `${Math.random() * 100}%`);
        emoji.style.setProperty('--emoji-drift', `${(Math.random() * 30 - 15).toFixed(2)}vw`);
        emoji.style.setProperty('--emoji-duration', `${(26 + Math.random() * 24).toFixed(2)}s`);
        emoji.style.setProperty('--emoji-delay', `${(-Math.random() * 24).toFixed(2)}s`);
        emoji.style.setProperty('--emoji-rotation', `${(Math.random() * 30 - 15).toFixed(2)}deg`);
        emoji.style.setProperty('--emoji-size', `${(1.4 + Math.random() * 1.6).toFixed(2)}rem`);
        emoji.style.setProperty('--emoji-opacity', `${(0.35 + Math.random() * 0.45).toFixed(2)}`);
        fragment.appendChild(emoji);
      }

      this.container.innerHTML = '';
      this.container.appendChild(fragment);
      this.container.classList.toggle('emoji-sky-layer--reduced', prefersReducedMotion.matches);
    },

    calculateDensity() {
      const area = window.innerWidth * window.innerHeight;
      const base = Math.round(area / 9000);
      return Math.max(48, Math.min(140, base));
    },

    observeResize() {
      if (this.resizeHandler) return;

      this.resizeHandler = () => {
        clearTimeout(this.resizeTimer);
        this.resizeTimer = setTimeout(() => this.populateEmojis(), 200);
      };

      window.addEventListener('resize', this.resizeHandler, { passive: true });
    }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => EmojiSkyTheme.init());
  } else {
    EmojiSkyTheme.init();
  }
})();

