body.emoji-sky-theme-active {
  background: transparent !important;
}

body.emoji-sky-theme-active #app,
body.emoji-sky-theme-active .v-application,
body.emoji-sky-theme-active .v-application--wrap,
body.emoji-sky-theme-active .v-main,
body.emoji-sky-theme-active .v-main__wrap,
body.emoji-sky-theme-active .v-main .v-container,
body.emoji-sky-theme-active .v-main .v-container--fluid {
  background-color: transparent !important;
  background-image: none !important;
}

.emoji-sky-layer {
  position: fixed;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: -1;
  transform: rotate(-12deg);
  opacity: 0.85;
}

.emoji-sky-layer::before {
  content: '';
  position: absolute;
  inset: -20%;
  background: radial-gradient(circle at top, rgba(255, 255, 255, 0.22), transparent 60%);
  opacity: 0.4;
  filter: blur(40px);
}

.emoji-sky-item {
  position: absolute;
  left: var(--emoji-left);
  bottom: -12vh;
  font-size: var(--emoji-size);
  transform: translate3d(-50%, 110vh, 0) rotate(var(--emoji-rotation));
  animation: emoji-sky-rise var(--emoji-duration) linear infinite;
  animation-delay: var(--emoji-delay);
  opacity: var(--emoji-opacity);
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, 0.15));
  will-change: transform, opacity;
}

.emoji-sky-layer--reduced .emoji-sky-item {
  animation-duration: 0.001s;
  animation-iteration-count: 1;
}

@keyframes emoji-sky-rise {
  0% {
    transform: translate3d(-50%, 110vh, 0) rotate(var(--emoji-rotation));
    opacity: 0;
  }
  10% {
    opacity: var(--emoji-opacity);
  }
  100% {
    transform: translate3d(calc(-50% + var(--emoji-drift)), -130vh, 0) rotate(var(--emoji-rotation));
    opacity: 0;
  }
}

@media (max-width: 600px) {
  .emoji-sky-layer {
    transform: rotate(-8deg);
    opacity: 0.75;
  }
}
